/**
 * JwtAuthGuard — gateway-layer JWT authentication using `jose` JWKS validation.
 *
 * Uses `createRemoteJWKSet` + `jwtVerify` with the algorithm allow-list from the
 * provider plan. Symmetric algorithms (HS*) and `alg:none` are always rejected.
 * JWKS refresh failure fails closed.
 *
 * Auto-generated by datrix-codegen-typescript from gateway.yaml config.
 * Do not edit manually.
 *
 * Issuer: library
 */
import {
  CanActivate,
  ExecutionContext,
  Injectable,
  Logger,
  UnauthorizedException,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { createRemoteJWKSet, jwtVerify } from 'jose';
import type { Request } from 'express';
import { IS_PUBLIC_KEY } from './public.decorator';

const JWKS_URI = 'library/.well-known/jwks.json';
const ISSUER = 'library';
const ALLOWED_ALGORITHMS: ReadonlyArray<string> = [
  'RS256',
];

const EXCLUDE_PATHS: ReadonlySet<string> = new Set([
  '/.well-known/jwks.json',
  '/api/v1/orders',
  '/api/v1/orders/:id',
  '/docs',
  '/health',
  '/openapi.json',
  '/redoc',
]);

/** Rejected algorithm prefixes (symmetric and none). */
const REJECTED_ALG_PREFIXES: ReadonlyArray<string> = ['HS'];
const REJECTED_ALG_NONE = 'none';

const _jwks = createRemoteJWKSet(new URL(JWKS_URI));

function assertAsymmetricAlgorithms(algorithms: ReadonlyArray<string>): void {
  for (const alg of algorithms) {
    if (alg.toLowerCase() === REJECTED_ALG_NONE) {
      throw new Error(
        `Algorithm 'none' is always rejected. Configure an asymmetric algorithm (RS*, ES*, PS*).`,
      );
    }
    for (const prefix of REJECTED_ALG_PREFIXES) {
      if (alg.startsWith(prefix)) {
        throw new Error(
          `Symmetric algorithm '${alg}' is rejected. Use asymmetric algorithms only (RS*, ES*, PS*).`,
        );
      }
    }
  }
}

// Validate algorithms at module load time — fail fast before the first request.
assertAsymmetricAlgorithms(ALLOWED_ALGORITHMS);

@Injectable()
export class JwtAuthGuard implements CanActivate {
  private readonly logger = new Logger(JwtAuthGuard.name);

  constructor(private readonly reflector: Reflector) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (isPublic) {
      return true;
    }

    const request = context.switchToHttp().getRequest<Request>();
    const requestPath = request.path;

    for (const pattern of EXCLUDE_PATHS) {
      if (requestPath === pattern || requestPath.startsWith(pattern + '/')) {
        return true;
      }
    }

    const token = this.extractTokenFromHeader(request);
    if (!token) {
      this.logger.warn(`gateway_auth_missing path=${requestPath}`);
      throw new UnauthorizedException('Authentication required');
    }

    try {
      const { payload } = await jwtVerify(token, _jwks, {
        issuer: ISSUER,
        algorithms: ALLOWED_ALGORITHMS as string[],
      });
      (request as unknown as Record<string, unknown>)['user'] = { claims: payload };
      this.logger.debug(`gateway_auth_verified path=${requestPath}`);
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      if (
        message.includes('JWKS') ||
        message.includes('fetch') ||
        message.includes('network') ||
        message.includes('connect')
      ) {
        this.logger.warn(`gateway_jwks_refresh_failed path=${requestPath} reason=${message}`);
        throw new UnauthorizedException('Authentication required');
      }
      this.logger.warn(`gateway_auth_failed path=${requestPath} reason=${message}`);
      throw new UnauthorizedException('Authentication required');
    }

    return true;
  }

  private extractTokenFromHeader(request: Request): string | undefined {
    const authHeader = request.headers.authorization;
    if (!authHeader) {
      return undefined;
    }
    const [type, token] = authHeader.split(' ');
    return type === 'Bearer' ? token : undefined;
  }
}
